// Valid ONLY when p > n. Shown to expose the failure mode for n >= p.
public long nCrFactorial(int n, int r, long p, long[] fact, long[] invFact) {
    if (r < 0 || r > n) return 0;
    // If n >= p, fact[n] % p == 0 (no inverse) and the table can't even be built for huge n.
    return fact[n] * invFact[r] % p * invFact[n - r] % p;
}

