import java.util.*;

class Lucas {
    private final long p;
    private final long[] fact, invFact;

    Lucas(long p) {
        this.p = p;
        int sz = (int) p;
        fact = new long[sz];
        invFact = new long[sz];
        fact[0] = 1 % p;
        for (int i = 1; i < sz; i++) fact[i] = fact[i - 1] * i % p;
        invFact[sz - 1] = modpow(fact[sz - 1], p - 2, p);
        for (int i = sz - 2; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % p;
    }

    // C(ni, ri) mod p for digits below p.
    private long smallNcr(long n, long r) {
        if (r < 0 || r > n) return 0;
        return fact[(int) n] * invFact[(int) r] % p * invFact[(int) (n - r)] % p;
    }

    long nCr(long n, long r) {
        long result = 1 % p;
        while (r > 0 || n > 0) {
            long ni = n % p, ri = r % p;
            if (ri > ni) return 0;           // digit binomial 0 -> whole answer 0
            result = result * smallNcr(ni, ri) % p;
            n /= p; r /= p;
        }
        return result;
    }

    private long modpow(long base, long exp, long mod) {
        long r = 1 % mod; base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) r = r * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return r;
    }
}

