class Lucas:
    def __init__(self, p: int) -> None:
        self.p = p
        self.fact = [1] * p
        for i in range(1, p):
            self.fact[i] = self.fact[i - 1] * i % p
        self.inv_fact = [1] * p
        self.inv_fact[p - 1] = pow(self.fact[p - 1], p - 2, p)
        for i in range(p - 2, -1, -1):
            self.inv_fact[i] = self.inv_fact[i + 1] * (i + 1) % p

    def _small_ncr(self, n: int, r: int) -> int:  # n, r < p
        if r < 0 or r > n:
            return 0
        return self.fact[n] * self.inv_fact[r] % self.p * self.inv_fact[n - r] % self.p

    def n_cr(self, n: int, r: int) -> int:
        result = 1 % self.p
        while n > 0 or r > 0:
            ni, ri = n % self.p, r % self.p
            if ri > ni:
                return 0                       # digit binomial 0 -> answer 0
            result = result * self._small_ncr(ni, ri) % self.p
            n //= self.p
            r //= self.p
        return result

